import { useState } from "react";

export function FeatureAnnouncement({
  title = "{{title}}",
  description = "{{description}}",
  ctaLabel = "{{ctaLabel}}",
  variant = "{{variant}}",
  accent = "{{accent}}",
}) {
  const [visible, setVisible] = useState(true);
  if (!visible) return null;
  const wrap = {
    banner: { display: "flex", alignItems: "center", gap: 14, borderRadius: 10 },
    card: { border: "1.5px solid #24143022", borderRadius: 12, maxWidth: 320, boxShadow: "0 8px 20px rgba(36,20,48,.1)" },
    spotlight: { position: "absolute", inset: 16, background: "#241430", color: "#FAF7F2", borderRadius: 14, boxShadow: "0 20px 40px rgba(36,20,48,.35)", display: "flex", flexDirection: "column", justifyContent: "center" },
  }[variant] ?? {};
  return (
    <div style={{ position: "relative", minHeight: 170, fontFamily: "system-ui, sans-serif", color: "#241430", background: "#FAF7F2", borderRadius: 12 }}>
      <div style={{ position: "relative", padding: "18px 40px 18px 20px", ...wrap }}>
        <button type="button" aria-label="Dismiss announcement" onClick={() => setVisible(false)}
          style={{ position: "absolute", top: 10, right: 12, background: "transparent", border: "none", fontSize: 16, lineHeight: 1, cursor: "pointer", color: variant === "spotlight" ? "#FAF7F2" : "#241430" }}>
          &times;
        </button>
        <span style={{ display: "inline-block", background: accent, color: "#241430", fontSize: 10, fontWeight: 700, textTransform: "uppercase", letterSpacing: ".04em", padding: "2px 8px", borderRadius: 999, marginBottom: 8 }}>New</span>
        <h3 style={{ margin: "0 0 4px", fontSize: 16, fontWeight: 600 }}>{title}</h3>
        <p style={{ margin: "0 0 12px", fontSize: 13.5, color: variant === "spotlight" ? "#FAF7F2cc" : "#241430cc" }}>{description}</p>
        <button type="button" style={{ background: accent, color: "#241430", border: "none", padding: "8px 16px", borderRadius: 8, fontWeight: 600, fontSize: 13.5, cursor: "pointer" }}>{ctaLabel}</button>
      </div>
    </div>
  );
}
